/**
 * A synthetic benchmark project at the design target's size (design 4.5): generated by commands,
 * with procedurally drawn art, so it is our own data and is never committed as files.
 *
 * At the default scale: 147 parts, 509 parameters, 720 art meshes of 36 vertices (half of them in
 * warps), 300 warps of 8 × 8 cells and one of 60 × 60, about 7,500 warp keyforms and 6,500 mesh
 * keyforms.
 */
import { MemoryAssetStore, Session } from '@mochi-maker/core';
import { encodePng } from '@mochi-maker/art';

export interface SyntheticScale {
  parts: number;
  parameters: number;
  meshes: number;
  warps: number;
  /** Keys per parameter. */
  keys: number;
}

export const DESIGN_TARGET: SyntheticScale = {
  parts: 147,
  parameters: 509,
  meshes: 720,
  warps: 300,
  keys: 5,
};

const GRID = 5; // mesh vertices per side: 6 × 6

export async function syntheticProject(
  scale: SyntheticScale = DESIGN_TARGET,
): Promise<{ session: Session; assets: MemoryAssetStore }> {
  const W = 4096;
  const H = 4096;
  const session = Session.create({
    width: W,
    height: H,
    pixelsPerUnit: W,
    originX: W / 2,
    originY: H / 2,
  });
  const assets = new MemoryAssetStore();
  // A few distinct images, shared by many layers, as small as a real model's parts are not.
  const images: string[] = [];
  for (let k = 0; k < 8; k++) {
    const w = 40;
    const data = new Uint8Array(w * w * 4);
    for (let y = 0; y < w; y++)
      for (let x = 0; x < w; x++)
        data.set([(k * 37) % 256, (x * 6) % 256, (y * 6) % 256, 255], 4 * (y * w + x));
    images.push(await assets.put(encodePng({ width: w, height: w, data })));
  }
  const keys = Array.from({ length: scale.keys }, (_, i) => -1 + (2 * i) / (scale.keys - 1));
  session.transact('synthetic project', (tx) => {
    tx.run('project.setExportSettings', { fileStem: 'synthetic', atlasSize: 4096 });
    const params: string[] = [];
    for (let i = 0; i < scale.parameters; i++)
      params.push(
        (
          tx.run('param.create', {
            exportId: `Param${i}`,
            min: -1,
            max: 1,
            default: 0,
            keys,
          }) as { uid: string }
        ).uid,
      );
    const parts: string[] = [];
    for (let i = 0; i < scale.parts; i++)
      parts.push(
        (
          tx.run('part.create', {
            exportId: `Part${i}`,
            ...(i > 0 ? { parent: parts[Math.floor((i - 1) / 4)] } : {}),
          }) as { uid: string }
        ).uid,
      );
    const warps: string[] = [];
    for (let i = 0; i < scale.warps + 1; i++) {
      const big = i === scale.warps;
      const n = big ? 60 : 8;
      const x = (i * 131) % (W - 400);
      const y = (i * 97) % (H - 400);
      const uid = (
        tx.run('deformer.createWarp', {
          exportId: `Warp${i}`,
          part: parts[i % parts.length],
          rows: n,
          cols: n,
          rect: big ? { x: 0, y: 0, width: W, height: H } : { x, y, width: 300, height: 300 },
        }) as { uid: string }
      ).uid;
      warps.push(uid);
      // Two bindings of `keys` keys each: keys² keyforms (one binding for the big warp).
      const bound = big
        ? [params[0]!]
        : [params[i % params.length]!, params[(i + 7) % params.length]!];
      for (const p of bound) tx.run('rig.addBinding', { target: uid, parameter: p });
      const cell = Object.fromEntries(bound.map((p) => [p, 1]));
      const grid: [number, number][] = [];
      for (let r = 0; r <= n; r++)
        for (let c = 0; c <= n; c++)
          grid.push(
            big
              ? [(c * W) / n + 8, (r * H) / n]
              : [x + (c * 300) / n + 10 * Math.sin(r), y + (r * 300) / n],
          );
      tx.run('keyform.set', { target: uid, cell, values: { grid } });
    }
    const uv: [number, number][] = [];
    for (let r = 0; r <= GRID; r++)
      for (let c = 0; c <= GRID; c++) uv.push([(c * 40) / GRID, (r * 40) / GRID]);
    const triangles: [number, number, number][] = [];
    for (let r = 0; r < GRID; r++)
      for (let c = 0; c < GRID; c++) {
        const a = r * (GRID + 1) + c;
        triangles.push([a, a + 1, a + GRID + 2], [a, a + GRID + 2, a + GRID + 1]);
      }
    for (let i = 0; i < scale.meshes; i++) {
      const inWarp = i % 2 === 1;
      const x = (i * 53) % (W - 100);
      const y = (i * 89) % (H - 100);
      const layer = (
        tx.run('layer.create', {
          name: `layer${i}`,
          asset: images[i % images.length],
          x,
          y,
          width: 40,
          height: 40,
        }) as { uid: string }
      ).uid;
      const positions = uv.map(([u, v]): [number, number] =>
        inWarp ? [0.2 + (0.6 * u) / 40, 0.2 + (0.6 * v) / 40] : [x + u, y + v],
      );
      const mesh = (
        tx.run('mesh.create', {
          exportId: `ArtMesh${i}`,
          part: parts[i % parts.length],
          ...(inWarp ? { deformer: warps[i % scale.warps] } : {}),
          layer,
          uv,
          positions,
          triangles,
        }) as { uid: string }
      ).uid;
      const bound = [params[(i * 3) % params.length]!, params[(i * 3 + 1) % params.length]!];
      for (const p of bound)
        tx.run('rig.addBinding', { target: mesh, parameter: p, keys: [-1, 0, 1] });
      tx.run('mesh.moveVertices', {
        target: mesh,
        cell: Object.fromEntries(bound.map((p) => [p, 1])),
        offset: inWarp ? [0.05, 0] : [8, 0],
      });
      tx.run('keyform.set', {
        target: mesh,
        cell: Object.fromEntries(bound.map((p) => [p, -1])),
        values: { opacity: 0.5 },
      });
    }
  });
  return { session, assets };
}
